-- Run once in Supabase SQL Editor. Create the owner Auth user first.
begin;
create table if not exists public.site_admins (user_id uuid primary key references auth.users(id) on delete cascade);
alter table public.site_admins enable row level security;
revoke all on public.site_admins from anon, authenticated;
create or replace function public.is_site_admin() returns boolean
language sql stable security definer set search_path = ''
as $$ select exists(select 1 from public.site_admins where user_id = (select auth.uid())); $$;
revoke all on function public.is_site_admin() from public;
grant execute on function public.is_site_admin() to anon, authenticated;
insert into public.site_admins(user_id)
select id from auth.users where lower(email) = 'keuaphasit.kho@gmail.com' and email_confirmed_at is not null
on conflict do nothing;
create table if not exists public.site_content (
 id integer primary key check(id=1),
 content jsonb not null check(jsonb_typeof(content)='object'),
 updated_at timestamptz not null default now()
);
alter table public.site_content enable row level security;
revoke all on public.site_content from anon, authenticated;
grant select on public.site_content to anon, authenticated;
grant update on public.site_content to authenticated;
drop policy if exists "Public read" on public.site_content;
create policy "Public read" on public.site_content for select to anon, authenticated using (true);
drop policy if exists "Owner update" on public.site_content;
create policy "Owner update" on public.site_content for update to authenticated using ((select public.is_site_admin())) with check ((select public.is_site_admin()));
