insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('product-images','product-images',true,5242880,array['image/jpeg','image/png','image/webp'])
on conflict(id) do update set public=true,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
drop policy if exists "Owner upload product images" on storage.objects;
create policy "Owner upload product images" on storage.objects for insert to authenticated
with check(bucket_id='product-images' and (select public.is_site_admin()));
commit;
-- Must return one owner. If zero, create and confirm the Auth user, then rerun.
select user_id from public.site_admins;
